output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "After entering the store, the shopper is obliged to take the entry cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": "at(1,5)"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart"
      },
      "events": {
        "item_pickup_attempt": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup_attempt",
          {
            "not": "cart_in_possession"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying groceries loose by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "becomes_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "becomes_hand_full"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "Once a shopper has taken a cart, they are obliged to return it to the cart-return bay before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "cart_returned_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_bay"
    }
  },
  {
    "id": "leave_cart_only_in_bay",
    "text": "A shopper is prohibited from putting the cart down anywhere except the cart-return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "cart_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "A shopper is prohibited from exiting unless the cart is already parked in the designated return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "exit_without_returned_cart": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "cart_parked_in_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_without_returned_cart"
    }
  },
  {
    "id": "no_carts_in_exit_corridor",
    "text": "Pushing a cart into the eastern exit corridor is prohibited.",
    "abstraction": {
      "state_properties": {
        "east_exit_corridor": {
          "or": [
            "at(7,0)",
            "at(8,0)",
            "at(9,0)",
            "at(7,1)",
            "at(8,1)",
            "at(9,1)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "enter_exit_corridor_with_cart": {
          "pre": {
            "and": [
              "MOVE",
              "pushing_cart"
            ]
          },
          "post": "east_exit_corridor"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          {
            "and": [
              "east_exit_corridor",
              "pushing_cart"
            ]
          },
          "enter_exit_corridor_with_cart"
        ]
      }
    }
  },
  {
    "id": "only_cart_and_shelf_interactions",
    "text": "The only permitted interactions are taking the entry cart, picking up items from recognized shelf-service cells, and returning the cart to the return bay.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": "at(1,5)",
        "cart_return_bay": "at(0,1)",
        "apple_service_cell": {
          "or": [
            "at(1,3)",
            "at(2,4)"
          ]
        },
        "bread_service_cell": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_service_cell": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_service_cell": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "recognized_shelf_service_cell": {
          "or": [
            "apple_service_cell",
            "bread_service_cell",
            "milk_service_cell",
            "eggs_service_cell"
          ]
        }
      },
      "events": {
        "permitted_entry_cart_pickup": {
          "pre": {
            "and": [
              "entry_cart_station",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "permitted_shelf_pickup": {
          "pre": {
            "and": [
              "recognized_shelf_service_cell",
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "permitted_cart_return": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": {
              "or": [
                "permitted_entry_cart_pickup",
                "permitted_shelf_pickup",
                "permitted_cart_return"
              ]
            }
          }
        ]
      }
    }
  }
]
